/// <summary>
/// MPJ_3338_AMEXCustomerPaymentProcessing
/// This class contains the business logic to automatically create AMEX payment proposals,
/// generate payments and send statements to customers.
/// </summary>
class METAMEXCustPaymProposalService extends SysOperationServiceBase
{
    LedgerJournalNameId             journalName;
    LedgerJournalTable              journalTable;
    METAMEXCustPaymProposalContract contract;
    Args                            args;
    Date                            sysDate;

}

Method.Source:
    /// <summary>
    /// Runs the actual operation.
    /// </summary>
    /// <param name = "_contract"><c>METAMEXCustPaymProposalContract</c></param>
    public void runOperation(METAMEXCustPaymProposalContract _contract)
    {
        #OCCRetryCount
        try
        {
            if (!this.isExecutingInBatch())
            {
                throw error ("@MET:BatchProcessingMustBeSelected");
            }

            ttsbegin;
            contract = _contract;
            
            this.initParameters();

            if (journalTable &&
                !journalTable.Posted)
            {
                this.runPaymentproposal();

                this.updateJournalNum();

                Info(strFmt("@MET:METAMEXPaymentJournalMsg", journalTable.JournalNum));

            }
            else
            {
                throw Error("@MET:AMEXJournalError");
            }
            ttscommit;

        }
        catch (Exception::Error)
        {
            error ("@MET:AMEXJobError");
            this.checkDeleteJournal(); //Delete journal if no lines are created.
        }
        catch (Exception::Deadlock)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::Deadlock;
            }
            else
            {
                retry;
            }
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }

        if (journalTable)
        {

            this.generatePayments();

            this.sendStatements(journalTable.JournalNum,
                                    _contract.parmFromDate(),
                                    _contract.parmToDate());

            this.checkDeleteJournal(); //Delete journal if no lines are created.
        }
    }

/// <summary>
/// This method updates the <c>CustParameters</c> with the journal created.
/// </summary>
private void updateJournalNum()
{
    CustParameters::METUpdateAMEXJournalNum(journalTable.JournalNum);
}

/// <summary>
/// Delete the <c>LedgerJournalTable</c> record created if there are no lines created.
/// </summary>
private void checkDeleteJournal()
{
    if (journalTable &&
        !journalTable.numOfLines())
    {
        journalTable.selectForUpdate(true);
        journalTable.delete();
    }
}

    /// <summary>
    /// Initialises requried parameters for the payment proposal processing
    /// </summary> 
    private void initParameters()
    {
        sysDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());

        journalName = contract.parmJournalName();
        if (contract.parmCreateJournal())
        {
            this.createJournal();
        }
        else
        {
            journalTable = LedgerJournalTable::find(CustParameters::find().METAMEXPaymJournalNum);
        }
        args = new Args();
        args.caller(this);
        args.record(journalTable);
        args.parmEnumType(enumNum(UserInteractive));
        args.parmEnum(UserInteractive::No);
        
        if (contract.parmRegion() == METAMEXRegion::AUS)
        {
            if(contract.parmPaymentRun() == CustAccountStatement::AMEXWeekly)
            {
                contract.parmFromDate(sysDate-7);
                contract.parmToDate(sysDate-1);
            }
            else if(contract.parmPaymentRun() == CustAccountStatement::AMEXFortnightly)
            {
                contract.parmFromDate(sysDate-14);
                contract.parmToDate(sysDate-1);
            }
            else if(contract.parmPaymentRun() == CustAccountStatement::AMEXMonthly)
            {
                contract.parmFromDate(dateStartMth(prevMth(sysDate)));
                contract.parmToDate(dateEndMth(prevMth(sysDate)));
            }
            else if(contract.parmPaymentRun() == CustAccountStatement::AMEXPeriod)
            {
                FiscalCalendarRecIdBase     fiscalCalendarRecId = Ledger::fiscalCalendar();

                contract.parmFromDate(FiscalCalendars::findPreviousPeriod(fiscalCalendarRecId, sysDate));
                contract.parmToDate(FiscalCalendars::findPrevPeriodEndDateByDate(fiscalCalendarRecId, sysDate));
            }
            else if(contract.parmPaymentRun() == CustAccountStatement::Yearly)
            {
                contract.parmFromDate(sysDate-365);
                contract.parmToDate(sysDate-1);
            }
        }
        else if(contract.parmRegion() == METAMEXRegion::NZL)
        {
            contract.parmFromDate(sysDate-365);
            contract.parmToDate(sysDate-1);
        }
    }

/// <summary>
/// Creates <c>LedgerJournalTable</c> record.
/// </summary>
private void createJournal()
{
    
    journalTable.clear();
    journalTable.initFromLedgerJournalName(journalName);
    journalTable.InUseBy = curUserId();
    journalTable.SystemBlocked = NoYes::Yes;
    journalTable.JournalNum = JournalTableData::newTable(journalTable).nextJournalId();
    journalTable.Name = strFmt("@MET:METAMEXJournalName",journalTable.Name, sysDate);
    journalTable.insert();
}

/// <summary>
/// ledger journal table buffer.
/// </summary>
///<returns><c>LedgerJournalTable</c></returns>
public LedgerJournalTable ledgerJournalTable()
{
    return journalTable;
}

/// <summary>
/// Executes automatic payment proposal logic.
/// </summary>
private void runPaymentproposal()
{
    METAMEXCreatePaymJournal_Cust::main(args);
}

/// <summary>
/// Executes generate payments logic.
/// </summary>
private void generatePayments()
{
    try
    {
        ttsbegin;
        METAMEXCustSumForPaym::Main(args);
        ttscommit;
    }
    catch (Exception::Error)
    {
        error(strFmt("@MET:METAMEXGeneratePaymentsError", journalTable.JournalNum));
    }
}

    /// <summary>
    /// Triggers business logic to send customer statements.
    /// </summary>
    /// <param name = "_journalId">Journal id.</param>
    /// <param name = "_fromDate">Fromdate</param>
    /// <param name = "_toDate">Todate</param>
    private void sendStatements(JournalId _journalId,
                            FromDate    _fromDate,
                            ToDate      _toDate)
    {
        SysOperationServiceController controller = new SysOperationServiceController(
                                                    classStr(METAMEXCustStmtSendService),
                                                    methodStr(METAMEXCustStmtSendService, sendStatements),
                                                    SysOperationExecutionMode::Synchronous);

        METAMEXCustStmtSendContract dataContract = controller.getDataContractObject() as METAMEXCustStmtSendContract;
        dataContract.parmJournalNum(_journalId);
        dataContract.parmFromDate(_fromDate);
        dataContract.parmToDate(_toDate);
        controller.runOperation();
    }

/// <summary>
/// Data contract class.
/// </summary>
/// <returns><c>METAMEXCustPaymProposalContract</c></returns>
public METAMEXCustPaymProposalContract contract()
{
    return contract;
}
